import { Icon, type IconName } from "@/registry/p1/internal/icons";
import "./embed.css";

export interface EmbedProps {
  kind: "video" | "social" | "map" | "generic";
  url: string;
  title: string;
  ratio: "16 / 9" | "4 / 3" | "1 / 1";
  caption: string;
  width: "contained" | "wide";
}

function providerOf(url: string, kind: EmbedProps["kind"]): string {
  const u = (url || "").toLowerCase();
  if (/youtu\.?be/.test(u)) return "YouTube";
  if (/vimeo/.test(u)) return "Vimeo";
  if (/wistia/.test(u)) return "Wistia";
  if (/twitter|x\.com/.test(u)) return "X / Twitter";
  if (/instagram/.test(u)) return "Instagram";
  if (/linkedin/.test(u)) return "LinkedIn";
  if (/maps|google\.com\/maps/.test(u)) return "Google Maps";
  return { video: "Video", social: "Social post", map: "Map", generic: "Embedded content" }[kind];
}

const ICON_BY_KIND: Record<EmbedProps["kind"], IconName> = {
  video: "external",
  social: "chat",
  map: "map-pin",
  generic: "external",
};

export function EmbedRender({ kind, url, title, ratio, caption, width }: EmbedProps) {
  const provider = providerOf(url, kind);
  const isVideo = kind === "video";
  return (
    <div className="p1-embed p1-block" data-width={width}>
      <div className="p1-embed__frame" data-kind={kind} style={{ aspectRatio: ratio }}>
        {isVideo ? (
          <div className="p1-embed__play" aria-hidden="true">
            <span className="p1-embed__play-triangle" />
          </div>
        ) : (
          <div className="p1-embed__placeholder">
            <Icon name={ICON_BY_KIND[kind]} className="p1-embed__placeholder-icon" />
            <div className="p1-embed__placeholder-label">{provider}</div>
          </div>
        )}
        <div className="p1-embed__provider-tag" data-kind={kind}>{provider}</div>
        {isVideo && title && (
          <div className="p1-embed__video-title">{title}</div>
        )}
      </div>
      {caption && <div className="p1-embed__caption">{caption}</div>}
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { EmbedRender, type EmbedProps } from "./embed";
export type { EmbedProps };

export const EmbedBlock: ComponentConfig<EmbedProps> = {
  fields: {
    kind: {
      type: "select" as const,
      options: [
        { label: "Video", value: "video" },
        { label: "Social", value: "social" },
        { label: "Map", value: "map" },
        { label: "Generic", value: "generic" },
      ],
    },
    url: {
      type: "text" as const,
      ai: { exclude: true },
    },
    title: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Short video title shown on the embed preview. Under 12 words." },
    },
    ratio: {
      type: "select" as const,
      options: [
        { label: "16 / 9", value: "16 / 9" },
        { label: "4 / 3", value: "4 / 3" },
        { label: "1 / 1", value: "1 / 1" },
      ],
    },
    caption: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Optional caption shown below the embed. 1 sentence." },
    },
    width: {
      type: "select" as const,
      options: [
        { label: "Contained", value: "contained" },
        { label: "Wide", value: "wide" },
      ],
    },
  },
  defaultProps: {
    kind: "video",
    url: "https://youtube.com/watch?v=demo",
    title: "Inside a Pantheon deploy — start to Live in 90 seconds",
    ratio: "16 / 9",
    caption: "",
    width: "wide",
  },
  render: EmbedRender,
};

export const meta = defineMeta({
  title: 'Embed',
  description: 'Responsive iframe embed for video (YouTube/Vimeo/Wistia), social posts, maps, or generic URLs with aspect-ratio and caption; use for media embeds.',
  categories: ["editorial"],
  published: true,
  registryDependencies: ["@p1/tokens","@p1/internal-icons"],
});

.p1-embed__frame {
  border-radius: var(--p1-radius-card);
  overflow: hidden;
  position: relative;
}

.p1-embed[data-width="contained"] { max-inline-size: var(--p1-container-narrow); }
.p1-embed[data-width="wide"] { max-inline-size: var(--p1-container-default); }

.p1-embed[data-width="contained"],
.p1-embed[data-width="wide"] {
  margin-inline: auto;
  padding-block: var(--p1-space-md);
  padding-inline: var(--p1-space-lg);
}

.p1-embed__frame[data-kind="video"] {
  background-color: var(--p1-surface-inverse);
}
.p1-embed__frame[data-kind="social"],
.p1-embed__frame[data-kind="map"],
.p1-embed__frame[data-kind="generic"] {
  background-color: color-mix(in oklch, var(--p1-surface-inverse) 6%, transparent);
  border: 1px solid var(--p1-border);
}

/* Centre content vertically and horizontally */
.p1-embed__play,
.p1-embed__placeholder {
  align-items: center;
  display: grid;
  inset: 0;
  justify-items: center;
  place-content: center;
  position: absolute;
}

.p1-embed__play {
  block-size: 4.5rem;
  border-radius: var(--p1-radius-pill);
  inset: 50% auto auto 50%;
  inline-size: 4.5rem;
  margin: -2.25rem 0 0 -2.25rem;
  place-content: center;
  background-color: var(--p1-warning);
  box-shadow: var(--p1-shadow-play);
}
.p1-embed__play-triangle {
  block-size: 0;
  border-block: 0.8125rem solid transparent;
  border-inline-start: 1.3125rem solid var(--p1-fg-default);
  inline-size: 0;
  margin-inline-start: 0.2rem;
}

.p1-embed__placeholder { gap: var(--p1-space-sm); text-align: center; }
.p1-embed__placeholder-icon {
  block-size: 2.25rem;
  color: var(--p1-fg-muted);
  inline-size: 2.25rem;
}
.p1-embed__placeholder-label {
  color: var(--p1-fg-muted);
  font-weight: var(--p1-weight-bold);
}

.p1-embed__provider-tag {
  font-size: var(--p1-text-sm);
  font-weight: var(--p1-weight-bold);
  letter-spacing: 0.12em;
  padding: var(--p1-space-sm) var(--p1-space-md);
  position: absolute;
  inset-block-start: 0;
  inset-inline-start: 0;
  text-transform: uppercase;
}
.p1-embed__provider-tag[data-kind="video"] { color: var(--p1-fg-inverse-subtle); }
.p1-embed__provider-tag:not([data-kind="video"]) { color: var(--p1-fg-muted); }

.p1-embed__video-title {
  bottom: var(--p1-space-md);
  color: var(--p1-fg-inverse);
  filter: drop-shadow(var(--p1-drop-shadow-text));
  font-size: var(--p1-text-base);
  font-weight: var(--p1-weight-bold);
  inset-block-end: var(--p1-space-md);
  inset-inline: var(--p1-space-lg);
  line-height: var(--p1-leading-tight);
  position: absolute;
}

.p1-embed__caption {
  color: var(--p1-fg-muted);
  font-size: var(--p1-text-sm);
  line-height: var(--p1-leading-normal);
  margin-block-start: var(--p1-space-sm);
}

